(function(){
'use strict';
const A=PatternLabApp,L=PatternTraitLens,B=PatternBeetles,$=id=>document.getElementById(id),popup=$('trait-lens-popup'),enabled=$('trait-lens-enabled');
const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let choices=[],keys=['size','antennaLength','horn'],selected=null,anchor={x:0,y:0},lastBox=null;
const full=()=>A.canViewGenetics();
function hide(){popup.hidden=true;selected=null;}
function position(){const w=popup.offsetWidth,h=popup.offsetHeight;popup.style.left=Math.max(8,Math.min(innerWidth-w-8,anchor.x+18))+'px';popup.style.top=Math.max(8,Math.min(innerHeight-h-8,anchor.y+14))+'px';}
function show(id,box){if(!enabled.checked||A.isBlocked())return;const modal=document.querySelector('dialog[open]');if(modal&&modal.id!=='keep')return hide();const b=A.getState().beetles[id];if(!b)return hide();const parent=box.id==='keep-bugs'?$('keep'):document.body;if(popup.parentElement!==parent)parent.append(popup);selected=id;lastBox=box;const values=L.rows(b,keys,{full:full()});popup.innerHTML='<div class="lens-portrait">'+B.draw(b,'lens')+'</div><div class="lens-readings"><strong>'+esc(b.name?b.name+' · '+b.id:b.id)+'</strong><dl>'+values.map(t=>'<div><dt>'+esc(t.label)+'</dt><dd><b>'+esc(t.display)+'</b>'+(t.unit?'<small>'+esc(t.unit)+'</small>':'')+'</dd></div>').join('')+'</dl></div>';popup.hidden=false;position();}
function populate(){choices=L.options(full());keys=keys.filter(k=>choices.some(t=>t.key===k));$('trait-lens-list').innerHTML=choices.slice().sort((a,b)=>a.label.localeCompare(b.label)).map(t=>'<option value="'+esc(t.label)+'"></option>').join('');for(let i=0;i<3;i++)$('lens-trait-'+(i+1)).value=choices.find(t=>t.key===keys[i])?.label||'';enabled.disabled=A.isBlocked();if(selected&&lastBox)show(selected,lastBox);}
function change(){const next=[];let invalid=false;for(let i=1;i<=3;i++){const input=$('lens-trait-'+i),value=input.value.trim(),t=choices.find(t=>t.label.toLowerCase()===value.toLowerCase());input.setAttribute('aria-invalid',String(!!value&&!t));if(value&&!t)invalid=true;else if(t){if(next.includes(t.key))invalid=true;else next.push(t.key);}}$('trait-lens-hint').textContent=invalid?'Choose listed traits, with a different trait in each slot.':'Hover over a beetle to read these traits. The card stays until you leave the tank or point at another beetle.';if(!invalid){keys=next;if(selected&&lastBox)show(selected,lastBox);}}
for(let i=1;i<=3;i++)$('lens-trait-'+i).addEventListener('input',change);
enabled.onchange=()=>{for(const id of ['tank-bugs','keep-bugs'])$(id).classList.toggle('lens-active',enabled.checked);if(!enabled.checked)hide();};
for(const id of ['tank-bugs','keep-bugs']){const box=$(id);box.addEventListener('pointermove',e=>{if(!enabled.checked||e.buttons)return;anchor={x:e.clientX,y:e.clientY};const bug=e.target.closest('button[data-id]');if(bug&&bug.dataset.id!==selected)show(bug.dataset.id,box);else if(selected&&!popup.hidden)position();});box.addEventListener('focusin',e=>{const bug=e.target.closest('button[data-id]');if(!bug)return;const r=bug.getBoundingClientRect();anchor={x:r.right,y:r.top};show(bug.dataset.id,box);});box.addEventListener('pointerleave',hide);box.addEventListener('pointerdown',hide);}
document.addEventListener('keydown',e=>{if(e.key==='Escape')hide();});document.addEventListener('click',e=>{if(e.target.closest('button')&&!e.target.closest('#trait-lens-controls'))hide();});window.addEventListener('resize',hide);window.addEventListener('pattern-state',populate);document.addEventListener('visibilitychange',()=>{if(document.hidden)hide();});$('keep').addEventListener('close',hide);populate();
})();
